# Find L-shapes properly
def find_all_components(cells):
    """Return list of connected components (each as set of positions)"""
    used = set()
    components = []
    for cell in cells:
        if cell in used:
            continue
        visited = set()
        stack = [cell]
        while stack:
            curr = stack.pop()
            if curr in visited or curr not in cells:
                continue
            visited.add(curr)
            r, c = curr
            for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in cells and (nr, nc) not in visited:
                    stack.append((nr, nc))
        components.append(visited)
        used.update(visited)
    return components

def is_l_shape(component):
    """Check if component forms an L-shape (has a corner with both horizontal and vertical neighbors)"""
    size = len(component)
    if size < 4:
        return False

    for cell in component:
        r, c = cell
        horiz = sum(1 for dc in [1, -1] if (r, c + dc) in component)
        vert = sum(1 for dr in [1, -1] if (r + dr, c) in component)
        if horiz > 0 and vert > 0:
            return True
    return False

