def get_largest_component(grid, color):
    """Get connected cells of largest size for given color"""
    cells = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color:
                cells.add((r, c))

    if not cells:
        return set()

    # BFS to get components
    used = set()
    largest = set()
    max_size = 0

    for cell in cells:
        if cell in used:
            continue

        # BFS
        visited = {cell}
        stack = [cell]
        while stack:
            curr = stack.pop()
            if curr in used or curr not in cells:
                continue
            used.add(curr)
            r, c = curr
            for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in cells and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    stack.append((nr, nc))

        if len(visited) > max_size:
            max_size = len(visited)
            largest = visited
        used.update(visited)

    return largest, max_size

