    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color:
                cells.add((r, c))

    components = []
    used = set()

    for cell in cells:
        if cell in used:
            continue

        # BFS to collect component
        visited = {cell}
        stack = [cell]
        while stack:
            curr = stack.pop()
            if curr in used or curr not in cells:
                continue
            used.add(curr)
            r, c = curr
            for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                nr, nc = r + dr, c + dc
                if (nr, nc) in cells and (nr, nc) not in visited:
